window.RP_SESSION={"id":"S-6363396d686d","messages":[{"id":"RP-III-0130485","time":"2026-07-29T08:23:00+09:00","room":"RP III","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":"오늘 아침도 창문으로 내리쬐는 햇살과, 창문, 창문?","characters":["P-6ba6a097816f"]},{"id":"RP-III-0130486","time":"2026-07-29T08:24:00+09:00","room":"RP III","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":"햇살이 못 들어오는군여! 아무튼 아침일찍 일어나 기지개를 쭈욱 핍다. 푹신푹신 이불과 이별하는 건 아깝지만, 오늘 밤이 되면 분명 다시 만나게 되겠죠.","characters":["P-6ba6a097816f"]},{"id":"RP-III-0130487","time":"2026-07-29T08:25:00+09:00","room":"RP III","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":"그렇담 이제 밤사이 쌓인 더러운 것들을 때찌해줄 시간임다! 예이!","characters":["P-6ba6a097816f"]},{"id":"RP-III-0130488","time":"2026-07-29T08:26:00+09:00","room":"RP III","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 목욕물도 복지에 포함되서 올리브는 정말 기쁨다.","characters":["P-6ba6a097816f"]},{"id":"RP-III-0130489","time":"2026-07-29T08:26:00+09:00","room":"RP III","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":"(캐릭터의 사생활 보호를 위해 검열된 장면입니다.)","characters":["P-6ba6a097816f"]},{"id":"RP-III-0130490","time":"2026-07-29T08:33:00+09:00","room":"RP III","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 씻으니까 개운하고 좋슴다! 그럼 이제 아침 식사를 하러 가야져!\n\n \"안녕하심까 카프레제 님! 안녕하심까 선배님들!\"\n\n 카프레제 님은 씨가 아님다. 제게 밥을 주시니 님임다.","characters":["P-6ba6a097816f"]},{"id":"RP-III-0130491","time":"2026-07-29T08:35:00+09:00","room":"RP III","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 그럼 다음 운동을 하러 나감다. 햇님께도 인사를 드려야겠져. 오늘도 포근포근 따...","characters":["P-6ba6a097816f"]},{"id":"RP-III-0130492","time":"2026-07-29T08:35:00+09:00","room":"RP III","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":"뜨겁네여. 넵.","characters":["P-6ba6a097816f"]},{"id":"RP-III-0130493","time":"2026-07-29T08:35:00+09:00","room":"RP III","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":"하지만 굴하지 않고 나가겠슴다. 괜찮슴다. 제가 더 강함다.","characters":["P-6ba6a097816f"]},{"id":"RP-III-0130494","time":"2026-07-29T08:36:00+09:00","room":"RP III","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 훈련장의 모래바닥을 튼튼한 두 발로 딪고 섬다. 그리고, 쭈욱-!","characters":["P-6ba6a097816f"]},{"id":"RP-III-0130495","time":"2026-07-29T08:37:00+09:00","room":"RP III","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":"두 손을 깍지껴서, 상하좌우로 늘려줍니다. 쭉쭉-","characters":["P-6ba6a097816f"]},{"id":"RP-III-0130496","time":"2026-07-29T08:38:00+09:00","room":"RP III","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":"양팔을 돌려서 어깨관절도 풀어줍니다. 밤새 굳은 근육들을 하나하나 제대로 잘 풀어줘야 청소나 훈련할 때 다치지 않슴다.","characters":["P-6ba6a097816f"]},{"id":"RP-III-0130497","time":"2026-07-29T08:41:00+09:00","room":"RP III","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":"계속해서 몸을 풀어줌다. 그러면...","characters":["P-6ba6a097816f"]},{"id":"RP-III-0130498","time":"2026-07-29T08:41:00+09:00","room":"RP III","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":"어? 매미! 맴맴매미!","characters":["P-6ba6a097816f"]},{"id":"RP-III-0130499","time":"2026-07-29T08:41:00+09:00","room":"RP III","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":"잡으러 가야겠슴닷--!","characters":["P-6ba6a097816f"]},{"id":"RP-III-0130500","time":"2026-07-29T08:41:00+09:00","room":"RP III","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-6ba6a097816f"]},{"id":"RP-III-0130501","time":"2026-07-29T08:41:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... see you again, cowboy.","characters":[]}]};
